/**
 * Annotates a Composable function to enable recomposition tracing.
 * When the annotated function recomposes, the reason and count will be logged
 * to Logcat, helping identify unnecessary recompositions.
 *
 * @see ComposeStabilityAnalyzer
 */
@Target(AnnotationTarget.FUNCTION)
@Retention(AnnotationRetention.BINARY)
@MustBeDocumented
annotation class TraceRecomposition

