/**
 * Returns true if this type matches any of the ignored type patterns
 * defined in the stability configuration file.
 */
internal fun String.isIgnoredType(ignoredPatterns: List<String>): Boolean {
  return ignoredPatterns.any { pattern ->
    this.contains(pattern, ignoreCase = true) || 
    this.matches(Regex(pattern))
  }
}

data class StabilityAnalyzerSettings(
  val enabled: Boolean = true,
  val enableInTestSources: Boolean = false,
  val showGutterIcons: Boolean = true,
  val showInlineHints: Boolean = true,
  val strongSkippingEnabled: Boolean = true,
  val stabilityConfigPath: String? = null,
  val ignoredTypePatterns: List<String> = emptyList(),
  val stableColor: String = "0xFF4CAF50",
  val unstableColor: String = "0xFFF44336"
) {
  companion object {
    val DEFAULT = StabilityAnalyzerSettings()
  }
}

internal fun buildStabilityTooltip(info: ComposableStabilityInfo): String {
  return buildString {
    append("Stability: ")
    append(if (info.isSkippable) "Skippable" else "Unskippable")
    append(" • Restartable: ")
    append(if (info.isRestartable) "Yes" else "No")
    append("\n")
    append("Stable parameters: ${info.stableParams}/${info.stableParams + info.unstableParams}")
    if (info.unstableParamNames.isNotEmpty()) {
      append("\nUnstable: ${info.unstableParamNames.joinToString()}")
    }
    info.receiverStability?.let {
      append("\nReceiver: $it")
    }
  }
}

