/**
 * Unstable: contains `var` property → treated as Stability.Unknown.
 * See Chapter 5.2: Class with Mutable Property and Issue 1: Accidental var Usage.
 */
class MutableProfile(
    val id: String,
    var name: String // mutable → unstable
)

/**
 * Fixed version: immutable data class with only stable types.
 * Will be inferred as Stability.Certain.
 */
@Immutable
data class Profile(
    val id: String,
    val name: String
)

/**
 * Interface marked with @Stable tells the compiler to treat all implementations
 * as stable regardless of the concrete type.
 * See Chapter 5.5: Interface with @Stable and Section 6.1: Stability Annotations.
 */
@Stable
interface UiState {
    val isLoading: Boolean
    val error: String?
}

@Immutable
data class SuccessState(
    override val isLoading: Boolean = false,
    override val error: String? = null,
    val data: String
) : UiState

/**
 * Sealed class with only stable types in its subtypes.
 * Objects and data classes with immutable properties are stable.
 * See Chapter 5.2 User-Defined Classes and 2.7 Stability Decision Tree.
 */
@Immutable
sealed class NavigationEvent {
    data class NavigateTo(val route: String) : NavigationEvent()
    data class OpenDetail(val itemId: Long) : NavigationEvent()
    object Back : NavigationEvent()
}

/**
 * Phase 1: Fast Path Type Checks (Chapter 3.2).
 * Primitives, String, and common stable types are immediately considered stable.
 */
fun isPrimitiveStableType(type: String): Boolean {
    return when (type) {
        "kotlin.Int",
        "kotlin.Long",
        "kotlin.Boolean",
        "kotlin.Float",
        "kotlin.Double",
        "kotlin.String" -> true
        else -> false
    }
}
